import { chmodSync, existsSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";

// Release binary only: the files nesev reads at runtime (built SPA, migrations, fonts, OCR helper) are embedded in the
// executable (build/manifest.ts, generated by scripts/build-binary.ts) and extracted once per build into
// <cache dir>/nesev/<version>-<build id>/, which then serves as APP_ROOT (lib/app-files.ts). Missing files (e.g. a
// cache cleanup) are restored on the next start. Must not import server modules: they read APP_ROOT on import.

/** [path relative to APP_ROOT, embedded file path ("/$bunfs/…")] */
export type EmbeddedFile = readonly [string, string];

type Env = Record<string, string | undefined>;

export function cacheDir(env: Env = process.env, platform = process.platform, home = homedir()): string {
  if (env.NESEV_CACHE_DIR) return resolve(env.NESEV_CACHE_DIR);
  if (platform === "darwin") return join(home, "Library", "Caches", "nesev");
  if (platform === "win32") return join(env.LOCALAPPDATA || join(home, "AppData", "Local"), "nesev", "cache");
  return join(env.XDG_CACHE_HOME || join(home, ".cache"), "nesev");
}

/** Embedded names carry a content hash (a-x63esczm.html), so this changes whenever any shipped file changes. */
export function buildId(files: readonly EmbeddedFile[]): string {
  const key = files.map(([rel, src]) => `${rel}\0${src}`).join("\n");
  return Bun.hash(key).toString(16).padStart(16, "0").slice(0, 10);
}

const MARKER = ".complete";

/** Extracts the embedded files (if needed) and returns the directory to use as APP_ROOT. */
export function extractEmbedded(files: readonly EmbeddedFile[], version: string, base = cacheDir()): string {
  const name = `${version}-${buildId(files)}`;
  const target = join(base, name);
  if (existsSync(join(target, MARKER)) && files.every(([rel]) => existsSync(join(target, rel)))) return target;

  mkdirSync(base, { recursive: true });
  const tmp = join(base, `.tmp-${name}-${process.pid}`);
  rmSync(tmp, { recursive: true, force: true });
  for (const [rel, src] of files) {
    const out = join(tmp, rel);
    mkdirSync(dirname(out), { recursive: true });
    writeFileSync(out, readFileSync(src));
    if (rel.startsWith("bin/")) chmodSync(out, 0o755);
  }
  writeFileSync(join(tmp, MARKER), `${files.length}\n`);
  rmSync(target, { recursive: true, force: true });
  try {
    renameSync(tmp, target);
  } catch (err) {
    // another nesev process extracted the same build at the same moment
    rmSync(tmp, { recursive: true, force: true });
    if (!existsSync(join(target, MARKER))) throw err;
  }
  // drop older builds (a running older version re-extracts its files when it starts again)
  for (const entry of readdirSync(base)) {
    if (entry !== name && !entry.startsWith(".tmp-")) rmSync(join(base, entry), { recursive: true, force: true });
  }
  return target;
}
